/** An entity's forms, as `ts_intl_entity` hands them out. */
export function entityForms(json) {
  const forms = typeof json === 'string' ? JSON.parse(json) : json;
  return Object.freeze({
    iast: forms.iast ?? '',
    name: forms.name ?? '',
    prose: forms.prose ?? '',
    abbrev: forms.abbrev,
    about: forms.about,
    indic: forms.indic,
    locative: forms.locative,
    short: forms.short,
    glyph: forms.glyph,
    gender: forms.gender,
    forms: Object.freeze(
      Object.fromEntries(Object.entries(forms).filter(([, text]) => typeof text === 'string')),
    ),
  });
}
